@Injectable({ providedIn: 'root' })
export class TodoStore {
  private readonly api = inject(TodoApi);
  private readonly _todos = signal<Todo[]>([]);       // sejf
  readonly todos = this._todos.asReadonly();           // okienko
  readonly openCount = computed(() =>
    this._todos().filter(t => !t.done).length);

  async toggle(id: number) {
    // 1. zmiana optymistyczna – UI reaguje od razu
    this._todos.update(l => l.map(t => t.id === id ? { ...t, done: !t.done } : t));
    try {
      await this.api.toggle(id);                       // 2. zapis na serwerze
    } catch {
      this._todos.update(l => l.map(t => t.id === id ? { ...t, done: !t.done } : t)); // 3. cofnięcie
    }
  }
}

