type OrdersState = { items: Order[]; loading: boolean; error: string | null };

@Injectable()
export class OrdersStore {
  private readonly api = inject(OrdersApi);
  private readonly state = signal<OrdersState>({ items: [], loading: false, error: null });

  readonly items = computed(() => this.state().items);
  readonly loading = computed(() => this.state().loading);
  readonly total = computed(() => this.items().reduce((s, o) => s + o.amount, 0));

  load() {
    this.state.update(s => ({ ...s, loading: true, error: null }));
    this.api.getAll().subscribe({
      next: items => this.state.update(s => ({ ...s, items, loading: false })),
      error: () => this.state.update(s => ({ ...s, loading: false, error: 'Błąd ładowania' })),
    });
  }
}

export const OrdersActions = createActionGroup({ source: 'Orders', events: {
  'Page Opened': emptyProps(),
  'Load Success': props<{ orders: Order[] }>(),
  'Load Failure': props<{ error: string }>(),
}});

export const ordersFeature = createFeature({ name: 'orders', // + selectOrders, selectLoading...
  reducer: createReducer(initialState,
    on(OrdersActions.pageOpened, s => ({ ...s, loading: true })),
    on(OrdersActions.loadSuccess, (s, { orders }) => ({ ...s, orders, loading: false })),
    on(OrdersActions.loadFailure, (s, { error }) => ({ ...s, error, loading: false })),
  ),
});

export const loadOrders = createEffect(
  (actions$ = inject(Actions), api = inject(OrdersApi)) => actions$.pipe(
    ofType(OrdersActions.pageOpened),
    switchMap(() => api.getAll().pipe(
      map(orders => OrdersActions.loadSuccess({ orders })),
      catchError(() => of(OrdersActions.loadFailure({ error: 'Błąd' }))))),
  ), { functional: true });

export const OrdersStore = signalStore(
  withState({ orders: [] as Order[], loading: false, filter: '' }),
  withComputed(({ orders, filter }) => ({
    visible: computed(() => orders().filter(o => o.customer.includes(filter()))),
  })),
  withMethods((store, api = inject(OrdersApi)) => ({
    setFilter(filter: string) { patchState(store, { filter }); },
    load: rxMethod<void>(pipe(
      tap(() => patchState(store, { loading: true })),
      switchMap(() => api.getAll().pipe(
        tapResponse({
          next: orders => patchState(store, { orders, loading: false }),
          error: () => patchState(store, { loading: false }),
        }))),
    )),
  })),
  withHooks({ onInit: store => store.load() }),
);

export class RegisterForm {
  private readonly fb = inject(NonNullableFormBuilder);

  readonly form = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(8)]],
    confirm: [''],
    newsletter: [false],
  }, { validators: [passwordsMatch] });

  submit() {
    if (this.form.invalid) { this.form.markAllAsTouched(); return; }
    const data = this.form.getRawValue(); // { email: string; password: string; ... }
    this.api.register(data).subscribe();
  }
}

export const passwordsMatch: ValidatorFn = group => {
  const { password, confirm } = group.value;
  return password === confirm ? null : { passwordsMismatch: true };
};

export function emailTaken(api: UsersApi): AsyncValidatorFn {
  return control => timer(400).pipe(          // proste opóźnienie
    switchMap(() => api.isEmailTaken(control.value)),
    map(taken => (taken ? { emailTaken: true } : null)),
    catchError(() => of(null)),               // awaria API nie blokuje formularza
  );
}

