import { form, required, email, minLength, FormField } from '@angular/forms/signals';

@Component({
  selector: 'app-login',
  imports: [FormField],
  template: `
    <input type="email" [formField]="f.email" />
    @if (f.email().touched() && f.email().invalid()) { <small>Podaj poprawny e-mail</small> }
    <input type="password" [formField]="f.password" />
    <button [disabled]="f().invalid()">Zaloguj</button>`,
})
export class Login {
  readonly model = signal({ email: '', password: '' });
  readonly f = form(this.model, p => {
    required(p.email); email(p.email);
    required(p.password); minLength(p.password, 8);
  });
}

export const SKIP_AUTH = new HttpContextToken<boolean>(() => false);

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(AuthService).accessToken();     // sygnał z tokenem
  if (!token || req.context.get(SKIP_AUTH) || !req.url.startsWith('/api')) {
    return next(req);                                  // bez zmian
  }
  return next(req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }));
};

// ŹLE: req.headers.set('Authorization', ...) – zwraca NOWE nagłówki, oryginał bez zmian
// użycie flagi: http.post('/api/login', body, { context: new HttpContext().set(SKIP_AUTH, true) })

export const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const toast = inject(ToastService);
  const auth = inject(AuthService);
  return next(req).pipe(
    retry({
      count: req.method === 'GET' ? 2 : 0,
      delay: (err: HttpErrorResponse, attempt) =>
        [0, 503, 504].includes(err.status) ? timer(2 ** attempt * 500) : throwError(() => err),
    }),
    catchError((err: HttpErrorResponse) => {
      if (err.status === 401) auth.logout();
      else if (err.status >= 500 || err.status === 0) toast.error('Problem z serwerem, spróbuj ponownie');
      return throwError(() => err);   // przekaż dalej – komponent może obsłużyć 400
    }),
  );
};

